import { Component, OnInit } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { MisCompras } from 'src/app/models/mis-compras';

@Component({
  selector: 'app-ejercicio38',
  templateUrl: './ejercicio38.component.html',
  styleUrls: ['./ejercicio38.component.css']
})
export class Ejercicio38Component implements OnInit {

  clienteConMasPedidos: string = '';
  totalProductos: number = 0;

  constructor(private misComprasService: MisComprasService) { }

  ngOnInit(): void {
    this.misComprasService.obtenerCompras().subscribe({
      next: (compras: MisCompras[]) => {
        this.procesarCompras(compras);
      },
      error: (error) => {
        console.error('Error al obtener las compras', error);
      }
    });
  }




  procesarCompras(compras: MisCompras[]): void {
    const clienteMap = new Map<string, { totalPedidos: number, totalProductos: number }>();

    compras.forEach((compra) => {
      if (!clienteMap.has(compra.emailUsuario)) {
        clienteMap.set(compra.emailUsuario, { totalPedidos: 0, totalProductos: 0 });
      }

      // Aquí obtengo los datos del cliente actual o creo un nuevo registro si no existía
      const datosCliente = clienteMap.get(compra.emailUsuario);

      // Aumentamos el número de pedidos
      datosCliente.totalPedidos++;
      // Sumamos la cantidad de productos de esta compra al total del cliente
      compra.productos.forEach((producto) => {
        datosCliente.totalProductos += producto.cantidad;
      });

      // Actualizamos la información en el mapa
      clienteMap.set(compra.emailUsuario, datosCliente);
    });

    let maxPedidos = 0;
    clienteMap.forEach((valor, clave) => {
      if (valor.totalPedidos > maxPedidos) {
        maxPedidos = valor.totalPedidos;
        this.clienteConMasPedidos = clave;
        this.totalProductos = valor.totalProductos;
      }
    });
  }



}

